cypress_script:
describe('Forgot Password Recovery Form', () => {
  it('should successfully submit the form with a valid email', () => {
    cy.visit('https://the-internet.herokuapp.com/forgot_password');
    cy.get('#email').type('test@example.com');
    cy.get('#form_submit').click();
    cy.url().should('include', 'forgot_password');
  });

  it('should not change the URL when submitting an empty form', () => {
    cy.visit('https://the-internet.herokuapp.com/forgot_password');
    cy.get('#form_submit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/forgot_password');
    cy.get('#flash-messages').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Forgot Password Recovery Form', () => {
  test('should successfully submit the form with a valid email', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/forgot_password');
    await page.fill('#email', 'test@example.com');
    await page.click('#form_submit');
    await expect(page).toHaveURL(/forgot_password/);
  });

  test('should not change the URL when submitting an empty form', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/forgot_password');
    await page.click('#form_submit');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/forgot_password');
    await expect(page.locator('#flash-messages')).toBeVisible();
  });
});
